from __future__ import annotations
import json, time
from dataclasses import asdict
from pathlib import Path

CLEANUP_SH = r"""#!/usr/bin/env bash
# git-cleanup.sh - generated by RepoDoctor
# NON-DESTRUCTIVE by default. Explicit --execute required.
# This script rewrites Git history, which is a destructive operation
# requiring coordination with every collaborator.
set -euo pipefail

MODE="dry-run"
if [[ "${1:-}" == "--execute" ]]; then MODE="execute"; fi

if ! command -v git >/dev/null 2>&1; then
  echo "git not found"; exit 2
fi
if ! command -v git-filter-repo >/dev/null 2>&1; then
  echo "git-filter-repo is required: https://github.com/newren/git-filter-repo"; exit 2
fi

if [[ ! -d .git ]]; then
  echo "Run from the repository root (no .git directory found)"; exit 2
fi

echo "Mode: $MODE"
echo "This script will remove the following paths from ALL history."
echo "You will need to force-push manually and have collaborators re-clone."
echo "This script will NEVER force-push automatically."

PATHS=(
__PATHS__
)

for p in "${PATHS[@]}"; do
  echo " - $p"
done

if [[ "$MODE" == "dry-run" ]]; then
  echo "Dry-run only. Re-run with --execute to perform the rewrite."
  exit 0
fi

for p in "${PATHS[@]}"; do
  git filter-repo --invert-paths --path "$p" --force
done

echo "Rewrite complete. Review 'git log --all --oneline', then push with:"
echo "  git push --force-with-lease --all"
echo "  git push --force-with-lease --tags"
"""

def write_cleanup_script(out_dir: Path, blobs) -> Path:
    paths = sorted({b.path for b in blobs if b.path})
    body = CLEANUP_SH.replace("__PATHS__", "\n".join(f'  "{p}"' for p in paths) or "  # (no paths found)")
    p = out_dir / "git-cleanup.sh"
    p.write_text(body, "utf-8")
    p.chmod(0o755)
    return p

def write_analysis_json(out_dir: Path, data: dict) -> Path:
    p = out_dir / "analysis.json"
    p.write_text(json.dumps(data, indent=2, default=str), "utf-8")
    return p

def write_health_md(out_dir: Path, *, config, meta, score, git_report,
                    functions, clusters, dep_graph, files, findings, limitations) -> Path:
    def fmt(x): return "—" if x is None else x
    stale = [b for b in git_report.branches if b.stale]
    high_cx = sorted([f for f in functions if f.complexity > config.complexity_refactor_threshold],
                     key=lambda f: f.complexity, reverse=True)[:20]
    md = []
    md.append(f"# RepoDoctor Health Report")
    md.append(f"_Generated: {time.strftime('%Y-%m-%d %H:%M:%S UTC', time.gmtime())}_\n")
    md.append(f"## Repository")
    md.append(f"- Target: `{config.target}`")
    md.append(f"- Git repository: {'yes' if git_report.is_git else 'no'}")
    if git_report.is_git:
        md.append(f"- HEAD: `{fmt(meta.head)}`")
        md.append(f"- Default branch: `{fmt(meta.default_branch)}`")
        md.append(f"- Branches: {meta.branch_count}")
        md.append(f"- Commits: {meta.commit_count}")
        md.append(f"- Repo age (days): {fmt(round(meta.repo_age_days,1) if meta.repo_age_days else None)}")
        md.append(f"- Clone latency (s): {round(meta.clone_latency_s,2)}")
    md.append("")
    md.append(f"## Scan configuration")
    md.append(f"- Deep Git audit: {config.deep_git_audit}")
    md.append(f"- Stale threshold: {config.stale_days}d")
    md.append(f"- Complexity threshold: {config.complexity_refactor_threshold}")
    md.append(f"- Clone min tokens/lines: {config.clone_min_tokens}/{config.clone_min_lines}")
    md.append(f"- Max deep audit bytes: {config.max_deep_audit_bytes}")
    md.append("")
    md.append(f"## Health score: **{score['score']}/100** (raw {score['raw_points']}/{score['max_evaluated']})")
    md.append("| Component | Points | Max | Detail |")
    md.append("|---|---:|---:|---|")
    for c in score["components"]:
        pts = "NOT EVALUATED" if c["points"] is None else c["points"]
        md.append(f"| {c['name']} | {pts} | {c['max_points']} | {c['detail']} |")
    md.append("")
    md.append("## Git hygiene")
    if git_report.is_git:
        md.append(f"### Branch decay — {len(stale)} stale (>= {config.stale_days}d)")
        if stale:
            md.append("| Branch | Last commit | Age (d) | Merged | Safe to delete |")
            md.append("|---|---|---:|---|---|")
            for b in stale[:50]:
                md.append(f"| `{b.name}` | `{b.last_commit[:12]}` | {b.age_days:.0f} | {b.merged_state} | {'yes' if b.safe_to_delete else 'no'} |")
        else:
            md.append("_No stale branches._")
        md.append("")
        md.append(f"### Historical object bloat")
        if git_report.blobs_evaluated:
            if not git_report.blobs:
                md.append("_No large blobs found._")
            else:
                md.append("| Path | Blob | Raw | Disk | Origin |")
                md.append("|---|---|---:|---:|---|")
                for b in git_report.blobs:
                    md.append(f"| `{b.path}` | `{b.blob_id[:12]}` | {b.raw_size} | {b.disk_size} | `{b.origin_commit[:12]}` |")
            if git_report.blob_note: md.append(f"\n> {git_report.blob_note}")
        else:
            md.append("NOT EVALUATED (standard mode — enable deep Git audit).")
    else:
        md.append("NOT EVALUATED (not a Git repository).")
    md.append("")
    md.append(f"## Complexity")
    md.append(f"Analyzed {len(functions)} functions. {sum(1 for f in functions if f.complexity > config.complexity_refactor_threshold)} exceed the threshold.")
    if high_cx:
        md.append("| File | Function | Lines | M | Class |")
        md.append("|---|---|---:|---:|---|")
        for f in high_cx:
            md.append(f"| `{f.file}` | `{f.name}` | {f.lines} | {f.complexity} | {f.classification} |")
    md.append("")
    md.append(f"## Structural clones")
    md.append(f"{len(clusters)} cluster(s).")
    for i, c in enumerate(clusters[:20], 1):
        md.append(f"- Cluster {i}: tokens={c.token_count}, hash=`{c.structural_hash[:12]}`")
        for m in c.members[:5]:
            md.append(f"    - `{m.file}:{m.start_line}-{m.end_line}` ({m.line_count} lines)")
    md.append("")
    md.append(f"## Dependency cycles")
    cycles = dep_graph.cycles if dep_graph else []
    md.append(f"{len(cycles)} cycle(s).")
    for i, cy in enumerate(cycles[:20], 1):
        md.append(f"- Cycle {i}: {' -> '.join(cy.get('path', []))}")
    md.append("")
    md.append(f"## Repository footprint")
    md.append(f"{len(files)} parsed source files.")
    md.append("")
    md.append(f"## Findings ({len(findings)})")
    if findings:
        md.append("| Severity | Category | Title | Path |")
        md.append("|---|---|---|---|")
        for f in findings[:200]:
            md.append(f"| {f.severity} | {f.category} | {f.title} | `{f.path}` |")
    md.append("")
    md.append(f"## Remediation")
    md.append("- Refactor functions exceeding complexity threshold.")
    md.append("- Deduplicate structural clones.")
    md.append("- Break dependency cycles via interfaces/inversion.")
    md.append("- Remove stale/merged branches.")
    md.append("- If large historical blobs exist, run the generated `git-cleanup.sh` (requires `git-filter-repo`).")
    md.append("")
    md.append(f"## Scan limitations")
    for l in limitations:
        md.append(f"- {l}")
    out = out_dir / "HEALTH.md"
    out.write_text("\n".join(md), "utf-8")
    return out
